import{_ as r,C as s,o as t,c as o,a2 as a,b as l,w as i,a as d,E as c,a3 as u}from"./chunks/framework.Brv5O9VI.js";const v=JSON.parse('{"title":"Step 2: Feature Inventory & Detailed Technical Specifications","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),h={name:"01-features.md"};function p(f,e,g,m,y,b){const n=s("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="step-2-feature-inventory-detailed-technical-specifications" tabindex="-1">Step 2: Feature Inventory &amp; Detailed Technical Specifications <a class="header-anchor" href="#step-2-feature-inventory-detailed-technical-specifications" aria-label="Permalink to &quot;Step 2: Feature Inventory &amp; Detailed Technical Specifications&quot;">​</a></h1><h2 id="master-feature-catalog" tabindex="-1">Master Feature Catalog <a class="header-anchor" href="#master-feature-catalog" aria-label="Permalink to &quot;Master Feature Catalog&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Feature Name</th><th style="text-align:left;">Core File &amp; Location</th><th style="text-align:left;">Primary Purpose</th><th style="text-align:left;">User-Facing Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>F1</strong></td><td style="text-align:left;">[Standard Identification via Dense Vector RAG](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/docs/features/F1-standard-identification-rag.md)</td><td style="text-align:left;">[<code>app.py:L73-L93</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L73-L93)</td><td style="text-align:left;">FastEmbed ONNX (bge-small) + FAISS (IndexFlatIP) top-1 nearest neighbor retrieval</td><td style="text-align:left;">Resolves matching IS/AIS standard code and gazette citations in &lt;20ms</td></tr><tr><td style="text-align:left;"><strong>F2</strong></td><td style="text-align:left;">[Regulatory Guardrailing &amp; Out-of-Domain Filter](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/docs/features/F2-regulatory-guardrail.md)</td><td style="text-align:left;">[<code>guardrail.py:L1-L42</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/guardrail.py#L1-L42)</td><td style="text-align:left;">4-tier filtering (blacklist, regex, statutory roots, 0.45 cosine threshold)</td><td style="text-align:left;">Blocks commercial/non-statutory noise (crypto, food, cutlery)</td></tr><tr><td style="text-align:left;"><strong>F3</strong></td><td style="text-align:left;">[Factory Readiness &amp; Gap Analysis Engine](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/docs/features/F3-factory-readiness-gap-engine.md)</td><td style="text-align:left;">[<code>gap_engine.py:L4-L59</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/gap_engine.py#L4-L59)</td><td style="text-align:left;">Dynamic weighted gap scoring for BIS Scheme-I and AIS Homologation</td><td style="text-align:left;">Computes exact readiness %, flags critical deficits, provides remedial actions</td></tr><tr><td style="text-align:left;"><strong>F4</strong></td><td style="text-align:left;">[Statutory Audit Pack CSV Export](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/docs/features/F4-statutory-audit-pack-export.md)</td><td style="text-align:left;">[<code>app.py:L140-L152</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L140-L152)</td><td style="text-align:left;">RFC 4180 CSV export via Python&#39;s <code>io.StringIO</code> and <code>csv.writer</code></td><td style="text-align:left;">One-click download of audit findings into ERP/Excel spreadsheets</td></tr><tr><td style="text-align:left;"><strong>F5</strong></td><td style="text-align:left;">[Conversational Officer &amp; Intent Resolver](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/docs/features/F5-conversational-compliance-officer.md)</td><td style="text-align:left;">[<code>app.py:L31-L59</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L31-L59)</td><td style="text-align:left;">Sub-microsecond regex/prefix intent resolution for small talk</td><td style="text-align:left;">Natural onboarding guidance without triggering unnecessary vector search</td></tr></tbody></table><hr><h2 id="complete-feature-matrix-dependencies" tabindex="-1">Complete Feature Matrix &amp; Dependencies <a class="header-anchor" href="#complete-feature-matrix-dependencies" aria-label="Permalink to &quot;Complete Feature Matrix &amp; Dependencies&quot;">​</a></h2>',5)),(t(),l(u,null,{default:i(()=>[c(n,{id:"mermaid-118",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20F5%5BF5%3A%20Small%20Talk%20Resolver%5D%20--%3E%7CIf%20Not%20Conversational%7C%20F1%5BF1%3A%20Dense%20Vector%20RAG%20%26%20Classification%5D%0A%20%20%20%20F1%20--%3E%20F2%5BF2%3A%204-Tier%20Domain%20Guardrail%5D%0A%20%20%20%20F2%20--%3E%7CIf%20Passed%7C%20F3%5BF3%3A%20Weighted%20Gap%20Engine%5D%0A%20%20%20%20F3%20--%3E%20F4%5BF4%3A%20CSV%20Audit%20Pack%20Export%5D%0A%20%20%20%20F2%20-.-%3E%7CIf%20Blocked%7C%20E1%5BReturn%20Out-of-Domain%20Explanation%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="feature-dependencies-table" tabindex="-1">Feature Dependencies Table <a class="header-anchor" href="#feature-dependencies-table" aria-label="Permalink to &quot;Feature Dependencies Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Prerequisites (Must Exist First)</th><th style="text-align:left;">Data Consumed</th><th style="text-align:left;">Output Emitted</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>F1 (RAG Search)</strong></td><td style="text-align:left;">Pre-computed <code>model2_rag_faiss.index</code>, <code>model2_corpus.json</code>, <code>FastEmbed</code></td><td style="text-align:left;">User product query string</td><td style="text-align:left;">Matched standard record &amp; cosine similarity score</td></tr><tr><td style="text-align:left;"><strong>F2 (Guardrail)</strong></td><td style="text-align:left;">F1 candidate match &amp; similarity score</td><td style="text-align:left;">Query, matched standard code, score</td><td style="text-align:left;">Boolean pass flag &amp; statutory explanation</td></tr><tr><td style="text-align:left;"><strong>F3 (Gap Engine)</strong></td><td style="text-align:left;">F1 matched standard, F2 validation, user checked documents</td><td style="text-align:left;">Document IDs list, standard string</td><td style="text-align:left;">Score percentage, status, critical flags, remediation list</td></tr><tr><td style="text-align:left;"><strong>F4 (CSV Export)</strong></td><td style="text-align:left;">F1 standard metadata, F3 readiness evaluation</td><td style="text-align:left;">Query text, document checklist</td><td style="text-align:left;">Formatted RFC-4180 CSV file stream</td></tr><tr><td style="text-align:left;"><strong>F5 (Small Talk)</strong></td><td style="text-align:left;">Pre-cached trigger list</td><td style="text-align:left;">User message string</td><td style="text-align:left;">Narrative onboarding reply</td></tr></tbody></table><hr><h2 id="say-it-out-loud-scripts-feature-by-feature" tabindex="-1">Say It Out Loud Scripts (Feature by Feature) <a class="header-anchor" href="#say-it-out-loud-scripts-feature-by-feature" aria-label="Permalink to &quot;Say It Out Loud Scripts (Feature by Feature)&quot;">​</a></h2><h3 id="f1-semantic-standard-identification" tabindex="-1">F1: Semantic Standard Identification <a class="header-anchor" href="#f1-semantic-standard-identification" aria-label="Permalink to &quot;F1: Semantic Standard Identification&quot;">​</a></h3><blockquote><p>&quot;I built the Semantic Standard Identification feature so that manufacturers and compliance officers don&#39;t have to manually comb through hundreds of Indian Standard gazettes to figure out which statutory rules apply to their product. When a user enters a product description like &#39;Ordinary Portland Cement 53 Grade&#39; into the chat box in App.jsx, the frontend sends an HTTP POST request to the /chat endpoint in app.py. The backend takes that text and passes it to an air-gapped FastEmbed model running BAAI/bge-small-en-v1.5 on CPU via ONNX Runtime. This converts the text into a 384-dimensional dense vector in about fourteen milliseconds without making any external cloud API calls. Next, that vector is passed to a FAISS IndexFlatIP vector index, which computes the inner product cosine similarity against our pre-indexed master corpus in model2_corpus.json in less than a millisecond. In parallel, our serialized Scikit-Learn model bis_product_department_model_v3.pkl predicts the governing department, such as Civil Engineering or Automotive Homologation. I chose this local ONNX and FAISS architecture over a third-party LLM API like OpenAI because industrial clients require complete confidentiality for unreleased products, and local embeddings guarantee zero token costs and sub-twenty-millisecond response times. If the user submits an empty string, the API throws an HTTP 400 validation error, and if the query doesn&#39;t match any statutory regulatory scope, our downstream guardrail catches it. One honest limitation right now is that the retrieval is set to k equals one, which only returns the single top standard; in the next version, I plan to expose the top-three candidate standards with confidence bars so users can evaluate composite products.&quot;</p></blockquote><h3 id="f2-regulatory-guardrailing-out-of-domain-filter" tabindex="-1">F2: Regulatory Guardrailing &amp; Out-of-Domain Filter <a class="header-anchor" href="#f2-regulatory-guardrailing-out-of-domain-filter" aria-label="Permalink to &quot;F2: Regulatory Guardrailing &amp; Out-of-Domain Filter&quot;">​</a></h3><blockquote><p>&quot;I built the Regulatory Guardrail feature to solve a classic problem with vector search: cosine similarity will always return a nearest neighbor even if the user asks something completely ridiculous like &#39;what is the price of bitcoin&#39; or &#39;give me a recipe for pizza.&#39; Without a guardrail, the system would hallucinate an official Indian Standard for unregulated goods. In app.py, right after FAISS returns the top-matching standard and its similarity score, the query is passed into check_domain_guardrail in guardrail.py. I designed this as a four-tier filtering pipeline. In tier one, it scans against a blacklist of non-statutory commercial terms like cryptocurrency, entertainment, or dining cutlery. In tier two, if the user explicitly typed a three-to-five digit standard number like 12269 or 156, it uses a regular expression to give an instant pass. In tier three, it looks for core statutory keywords like cement, rebar, or battery; if one is present and the vector similarity is at least 0.20, it passes. Finally, in tier four, any generalized product description must clear a dense semantic similarity threshold of 0.45. I chose this hybrid approach of rule-based regex combined with vector scoring over an LLM-based safety checker because it executes in less than a tenth of a millisecond and requires zero tokens or GPU memory. When a query fails, the backend returns a polite explanation stating that the product does not fall under statutory BIS or AIS mandates and suppresses the audit pack. One trade-off is that very novel or emerging products that don&#39;t share our defined roots might require tuning the 0.45 similarity threshold.&quot;</p></blockquote><h3 id="f3-factory-readiness-gap-analysis-engine" tabindex="-1">F3: Factory Readiness &amp; Gap Analysis Engine <a class="header-anchor" href="#f3-factory-readiness-gap-analysis-engine" aria-label="Permalink to &quot;F3: Factory Readiness &amp; Gap Analysis Engine&quot;">​</a></h3><blockquote><p>&quot;I built the Factory Readiness Gap Engine so that factories don&#39;t just find out which standard applies, but know exactly whether they can pass a surprise government audit tomorrow morning. In gap_engine.py, the evaluate_readiness function dynamically detects whether the identified standard belongs to Bureau of Indian Standards Scheme-I or Automotive Industry Standards Homologation. If the standard contains the letters &#39;AIS&#39;, it activates our automotive checklist; otherwise, it defaults to the BIS Scheme-I checklist. It then matches the factory&#39;s verified artifacts against weighted criteria totaling one hundred percent. For example, under BIS Scheme-I, having clause-specific in-house test benches carries twenty-five percent weight, while valid NABL calibration certificates carry fifteen percent. If any mandatory item marked critical is missing, the engine automatically flags a critical deficit and drops the status to Non-Compliant, even if the factory has a passing numerical score. I selected a transparent, deterministic rule-based scoring engine instead of an LLM because compliance calculations must be completely mathematically reproducible and auditable in legal proceedings. When evaluated, the engine returns an exact percentage, a list of specific missing items, and the exact remediation action, which renders live on the React frontend. One limitation is that currently documents are verified via checkbox selection; in future releases, we plan to parse uploaded PDF certificates using optical character recognition to verify NABL accreditation numbers automatically.&quot;</p></blockquote><h3 id="f4-statutory-audit-pack-csv-export" tabindex="-1">F4: Statutory Audit Pack CSV Export <a class="header-anchor" href="#f4-statutory-audit-pack-csv-export" aria-label="Permalink to &quot;F4: Statutory Audit Pack CSV Export&quot;">​</a></h3><blockquote><p>&quot;I built the Statutory Audit Pack Export feature so that quality managers can immediately download an official compliance record and share it with plant managers or regulatory inspectors without doing manual data entry. When the user clicks the Export CSV button on an audit card in App.jsx, the frontend issues a POST request to /audit/export in app.py, carrying the query text and the list of checked factory documents. The backend retrieves the matched standard from FAISS, computes the gap evaluation, and calls generate_csv_report in gap_engine.py. This function utilizes Python&#39;s native csv writer and StringIO to structure the report with the official standard title, Quality Control Order notification, assigned NABL laboratory, computed readiness score, and an itemized breakdown of every missing document along with its specific remedial action. The backend streams this as a plain text response with a text/csv MIME type and a Content-Disposition attachment header. The frontend turns the stream into a dynamic browser Blob URL and triggers an automatic download. I chose CSV over PDF for the initial release because compliance officers and operations managers need to import audit findings directly into enterprise Excel trackers and ERP systems. One limitation is that it currently only outputs CSV; adding a styled PDF export with official QR code verification is our next planned milestone.&quot;</p></blockquote><h3 id="f5-conversational-compliance-officer" tabindex="-1">F5: Conversational Compliance Officer <a class="header-anchor" href="#f5-conversational-compliance-officer" aria-label="Permalink to &quot;F5: Conversational Compliance Officer&quot;">​</a></h3><blockquote><p>&quot;I built the Conversational Compliance Officer feature because in real-world usage, users don&#39;t always start by typing a rigid product code; they often begin with &#39;hello&#39;, &#39;who are you&#39;, or &#39;how do I use this.&#39; In app.py, before executing the Scikit-Learn classifier or generating dense ONNX embeddings, the chat endpoint passes the raw message to is_conversational. This helper checks if the query matches our list of conversational triggers like &#39;namaste&#39;, &#39;help&#39;, or &#39;thanks&#39;. If a match is found, resolve_small_talk routes the prompt to a pre-defined regulatory guidance message. For instance, if the user asks &#39;who are you&#39;, it immediately clarifies that it is an air-gapped compliance officer built to audit products against Indian Standards and Automotive AIS regulations, and gives them examples of valid queries like &#39;Portland Pozzolana Cement.&#39; I chose this rule-based short-circuit rather than letting an embedding model process small talk because it executes in less than a microsecond, eliminates unnecessary vector computation, and prevents the system from accidentally matching &#39;hello&#39; to a random steel or chemical standard. When it responds, it sets the audit data field to null so the frontend displays a clean narrative bubble without rendering an empty audit card.&quot;</p></blockquote>',14))])}const F=r(h,[["render",p]]);export{v as __pageData,F as default};
